// Custom menu type and client screen pairing
public class MyMenu extends AbstractContainerMenu {
    public MyMenu(int id, Inventory inv) { super(MyMenus.MY_MENU.get(), id); }
    @Override public boolean stillValid(Player player) { return true; }
}

public class MyMenuScreen extends AbstractContainerScreen<MyMenu> {
    public MyMenuScreen(MyMenu menu, Inventory inv, Component title) { super(menu, inv, title); }
    @Override protected void renderBg(GuiGraphics gfx, float partialTick, int mouseX, int mouseY) {}
}

// MenuScreens is vanilla-registered for built-in menus.
